function photoUploadHtml(){return `<div class="photo-upload full"><div class="row between"><b class="small">Fotos</b><span class="tiny muted">Até 6 imagens</span></div><div class="photo-previews" id="photo-previews">${photoPreviews()}</div><div id="photo-progress" role="status" aria-live="polite" class="small muted" style="display:flex;align-items:center;gap:10px;margin:0"><md-circular-progress indeterminate aria-hidden="true" style="--md-circular-progress-size:24px;display:none"></md-circular-progress><span></span></div><label for="upload-photos">${icon('add_photo_alternate')}Adicionar fotos<input type="file" id="upload-photos" accept="image/jpeg,image/png,image/webp,image/avif" multiple class="sr"></label><p class="form-note">A primeira foto será a capa. Você pode remover e adicionar outras imagens.</p></div>`;}
function photoPreviews(){return (editor?.photos||[]).map((p,i)=>`<div class="photo-preview"><img src="${image(p)}" alt="Foto ${i+1}">${iconBtn('close','remove-photo',String(i),'Remover foto '+(i+1))}</div>`).join('');}
function openItemEditor(kind='desapego',id=null,draftId=null){
 if(!canPost())return;const original=id?itemById(id):draftId?state.drafts.find(x=>x.id===draftId):null;if(id&&(!original?.mine||original.city!==state.homeCity))return;
 const x=original||{title:'',desc:'',hood:'',kind,numPrice:'',photos:[],beds:'',area:'',parking:'',condo:''};kind=x.kind||kind;
 editor={kind:'item',type:kind,id,draftId,photos:[...(x.photos||[])]};editorDirty=false;
 showDialog(id?'Editar anúncio':kind==='imovel'?'Anunciar imóvel':'Anunciar desapego',`<div class="form-grid">${field('item-title','Título do anúncio',x.title,'required minlength="5" maxlength="100" class="full"')}${field('item-price',kind==='imovel'?'Aluguel mensal (R$)':'Preço (R$)',x.numPrice,'type="number" min="1" step="0.01" required inputmode="decimal"')}${selectField('item-hood','Bairro',[['','Escolher bairro'],...HOODS],x.hood,'required')}${kind==='imovel'?`${field('item-beds','Quartos',x.beds,'type="number" min="0" max="20" required')}${field('item-area','Área (m²)',x.area,'type="number" min="10" max="100000" required')}${field('item-parking','Vagas',x.parking,'type="number" min="0" max="20"')}${field('item-condo','Condomínio (R$)',x.condo||'','type="number" min="0" inputmode="decimal"')}`:''}${field('item-desc','Descrição',x.desc,'type="textarea" rows="4" required minlength="12" maxlength="2000" class="full"')}${photoUploadHtml()}</div><p class="form-note">Publicado em ${esc(state.homeCity)}. O endereço exato não aparece no anúncio.</p>`,`${!id?btn('Salvar rascunho','save-draft','','text'):btn('Cancelar','close-dialog','','text')}${btn(id?'Salvar alterações':'Publicar anúncio','submit-item','','filled')}`,'editor');
}
function itemForm(){return {title:$('#item-title').value.trim(),numPrice:Number($('#item-price').value),hood:$('#item-hood').value,desc:$('#item-desc').value.trim(),kind:editor.type,photos:[...editor.photos],beds:$('#item-beds')?Number($('#item-beds').value):null,area:$('#item-area')?Number($('#item-area').value):null,parking:$('#item-parking')?Number($('#item-parking').value):null,condo:$('#item-condo')?Number($('#item-condo').value):0};}
function validFields(ids){let first=null;for(const id of ids){const e=$('#'+id);if(e?.reportValidity&&!e.reportValidity())first??=e;}first?.focus();return !first;}
async function submitItem(){
 if(!editor||!canPost())return;if(!validFields(['item-title','item-price','item-hood','item-desc',...(editor.type==='imovel'?['item-beds','item-area']:[])]))return;
 const data=itemForm();const itemProblem=data.title.length<5?'O título precisa de pelo menos 5 letras.':data.numPrice<=0?'Informe um preço maior que zero.':!data.hood?'Escolha o bairro.':data.desc.length<12?'Descreva o anúncio com pelo menos 12 caracteres.':'';if(itemProblem){notify(itemProblem,'error');return;}
 const id=editor.id||uid('i'),draftId=editor.draftId,existing=itemById(id);
 const ok=mutate(()=>{if(existing)Object.assign(existing,data,{price:money(data.numPrice),per:data.kind==='imovel'?'/mês':'',updatedAt:Date.now(),demo:data.photos.some(p=>!p.startsWith('data:'))});else state.items.unshift({...data,id,city:state.homeCity,price:money(data.numPrice),per:data.kind==='imovel'?'/mês':'',status:'active',mine:true,seller:state.profile.name,sini:initals(state.profile.name),note:'Membro da comunidade',saved:false,createdAt:Date.now(),views:0,demo:false});if(draftId)state.drafts=state.drafts.filter(d=>d.id!==draftId);},{redraw:false});
 if(ok){await closeDialog(true);navigate('anuncio',id);notify(existing?'Anúncio atualizado':'Anúncio publicado');}
}
async function saveDraft(){if(!editor)return;const data=itemForm(),id=editor.draftId||uid('d');const ok=mutate(()=>{const old=state.drafts.find(d=>d.id===id);if(old)Object.assign(old,data,{at:Date.now()});else state.drafts.unshift({...data,id,at:Date.now()});},{redraw:false});if(ok){await closeDialog(true);myAdsFilter='drafts';navigate('meus-anuncios');notify('Rascunho salvo');}}
